import os
from click.testing import CliRunner
from click import group, command, option

@group()
def cli():
    pass

@cli.command()
@option("--fast", "mode_flag", is_flag=True, flag_value="fast")
@option("--mode", "mode_env", envvar="SHIPIT_MODE", default=None, hidden=True)
def deploy(mode_flag, mode_env):
    """Deploy the current build."""
    mode = mode_flag or mode_env or "safe"
    print(f"deploying in {mode} mode")

runner = CliRunner()

def test_default():
    result = runner.invoke(cli, ['deploy'])
    print(f"Default: {result.output.strip()}")

def test_fast_flag():
    result = runner.invoke(cli, ['deploy', '--fast'])
    print(f"Fast flag: {result.output.strip()}")

def test_env_var_fast():
    result = runner.invoke(cli, ['deploy'], env={'SHIPIT_MODE': 'fast'})
    print(f"Env var fast: {result.output.strip()}")

def test_env_var_canary():
    result = runner.invoke(cli, ['deploy'], env={'SHIPIT_MODE': 'canary'})
    print(f"Env var canary: {result.output.strip()}")

if __name__ == '__main__':
    test_default()
    test_fast_flag()
    test_env_var_fast()
    test_env_var_canary()
